-- Generated from owner-approved production menu CSV files. Review before applying.
-- Idempotent upserts only: no menu rows, orders, or immutable snapshots are deleted.
on conflict(id) do update set name=excluded.name,description=excluded.description,sort_order=excluded.sort_order,active=excluded.active;

on conflict(id) do update set category_id=excluded.category_id,name=excluded.name,description=excluded.description,price=excluded.price,image=excluded.image,available=excluded.available,sort_order=excluded.sort_order;
